import { SchemaForm, type FormSchema, type SchemaFormSubmitDetail } from '@absoluteui/components/schema-form';

const schema: FormSchema = {
  type: 'object',
  title: 'Leave request',
  required: ['type', 'from', 'days'],
  properties: {
    type: { type: 'string', title: 'Leave type', oneOf: [{ const: 'annual', title: 'Annual leave' }, { const: 'sick', title: 'Sick leave' }, { const: 'other', title: 'Other' }] },
    reason: { type: 'string', title: 'Reason', maxLength: 500 },
    from: { type: 'string', title: 'First day', format: 'date' },
    days: { type: 'integer', title: 'Working days', minimum: 1, maximum: 30 },
  },
};
const host = document.createElement('div');
document.body.append(host);
const form = SchemaForm.create(host, {
  schema,
  uiSchema: { columns: 2, fields: { reason: { widget: 'textarea', visibleIf: { field: 'type', equals: 'other' }, span: 2 } } },
  submitLabel: 'Request leave',
});
host.addEventListener('aui-submit', (event) => {
  console.log((event as CustomEvent<SchemaFormSubmitDetail>).detail.value);
});
form.getValue();

import { SchemaForm, type FormSchema } from '@absoluteui/components/schema-form';

const schema: FormSchema = {
  type: 'object',
  properties: {
    name: { type: 'string', title: 'Name' },
    contacts: {
      type: 'array',
      title: 'Emergency contacts',
      minItems: 1,
      maxItems: 3,
      items: { type: 'object', title: 'Contact', required: ['name', 'phone'], properties: { name: { type: 'string', title: 'Name' }, phone: { type: 'string', title: 'Phone' } } },
    },
  },
};
const host = document.createElement('div');
document.body.append(host);
const form = SchemaForm.create(host, {
  schema,
  validate: async (value, signal) => {
    const response = await fetch('/api/onboarding/check', { method: 'POST', body: JSON.stringify(value), signal });
    const body: unknown = await response.json();
    return typeof body === 'object' && body !== null ? Object.fromEntries(Object.entries(body).filter((e): e is [string, string] => typeof e[1] === 'string')) : {};
  },
});
// Server errors by JSON Pointer:
form.setErrors({ '/contacts/0/phone': 'Enter a phone number we can call.' });
